#!/bin/sh
set -eu
root=${1:?"usage: ROLLBACK.sh TARGET_REPO_COPY"}
tmp=${TMPDIR:-/tmp}/gsa-async-rollback-$$.patch
b64=${tmp}.b64
trap 'rm -f "$tmp" "$b64"' EXIT HUP INT TERM
sed '1,/^__PATCH__$/d' "$0" > "$b64"
if base64 -d "$b64" 2>/dev/null | gzip -d > "$tmp" 2>/dev/null; then :
elif base64 -D "$b64" 2>/dev/null | gzip -d > "$tmp"; then :
else echo 'cannot decode embedded rollback patch' >&2; exit 2
fi
(cd "$root" && git apply --check -R "$tmp" && git apply -R "$tmp")
echo "rollback restored synchronous baseline in $root"
exit 0
__PATCH__

